(function(E){ const x = E["exam-05"] = E["exam-05"] || {units:{}}; (x.units = x.units || {})["x05-s"] = {"id":"x05-s","patterns":["S1-frame","S1-places","S2-object","S3-culture","TR-short","PARA-discuss"],"title":{"en":"Speaking","tr":"Speaking","fa":"Speaking (صحبت کردن)"},"objective":{"en":"In this lesson you will learn to take the whole Speaking test: answer everyday questions in two or three sentences, describe a show you would like to see again for two minutes, and discuss live performance with a view, a reason and an example.","tr":"Bu derste Speaking sınavının tamamını yapmayı öğreneceksin: günlük soruları iki üç cümleyle cevaplayacak, yeniden görmek istediğin bir gösteriyi iki dakika anlatacak ve canlı performansı bir görüş, bir neden ve bir örnekle tartışacaksın.","fa":"در این درس یاد می‌گیری کل آزمون Speaking را انجام بدهی: به سؤال‌های روزمره با دو سه جمله جواب بدهی، دو دقیقه درباره‌ی اجرایی که دوست داری دوباره ببینی حرف بزنی و درباره‌ی اجرای زنده با یک نظر، یک دلیل و یک مثال بحث کنی."},"sessions":[["explain"],["sets"],["exit"]],"explain":{"title":{"en":"Speaking: Parts 1, 2 and 3","tr":"Speaking: Part 1, 2 ve 3","fa":"Speaking: بخش‌های ۱، ۲ و ۳"},"objective":{"en":"In this lesson you will learn to take the whole Speaking test: answer everyday questions in two or three sentences, describe a show you would like to see again for two minutes, and discuss live performance with a view, a reason and an example.","tr":"Bu derste Speaking sınavının tamamını yapmayı öğreneceksin: günlük soruları iki üç cümleyle cevaplayacak, yeniden görmek istediğin bir gösteriyi iki dakika anlatacak ve canlı performansı bir görüş, bir neden ve bir örnekle tartışacaksın.","fa":"در این درس یاد می‌گیری کل آزمون Speaking را انجام بدهی: به سؤال‌های روزمره با دو سه جمله جواب بدهی، دو دقیقه درباره‌ی اجرایی که دوست داری دوباره ببینی حرف بزنی و درباره‌ی اجرای زنده با یک نظر، یک دلیل و یک مثال بحث کنی."},"stats":[{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"11-14 min","tr":"11-14 dk","fa":"۱۱ تا ۱۴ دقیقه"}},{"label":{"en":"Parts","tr":"Kısım","fa":"بخش"},"value":"3"},{"label":{"en":"Part 2 talk","tr":"Part 2 konuşması","fa":"صحبت Part 2"},"value":{"en":"2 min","tr":"2 dk","fa":"۲ دقیقه"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: cycling, a show, live performance","tr":"Bu sınav: bisiklet, bir gösteri, canlı performans","fa":"این آزمون: دوچرخه‌سواری، یک اجرا، اجرای زنده"},"intro":{"en":"The three parts are linked: Part 1 is about you, Part 2 is one thing you describe from a card, and Part 3 widens the Part 2 topic to people in general. Cards about an object, a film or a show are the second most common Part 2 type.","tr":"Üç kısım birbirine bağlıdır: Part 1 seninle ilgili, Part 2 karttan anlattığın tek bir şey ve Part 3, Part 2 konusunu genel olarak insanlara genişletir. Bir nesne, film ya da gösteri hakkındaki kartlar en sık çıkan ikinci Part 2 türüdür.","fa":"سه بخش به هم وصل‌اند: Part 1 درباره‌ی خودت است، Part 2 چیزی است که از روی کارت توصیف می‌کنی و Part 3 موضوع Part 2 را به آدم‌ها به‌طور کلی گسترش می‌دهد. کارت‌هایی درباره‌ی یک شیء، فیلم یا اجرا دومین نوع رایج Part 2 هستند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x05-s1-ctx","exam":true,"patterns":["S1-frame","S1-places"],"often":{"pattern":"S1-places","n":8,"of":40,"label":{"en":"Comes up often in the real exam: 8 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 8’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۸ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 1: you, then cycling","tr":"Part 1: sen, sonra bisiklet","fa":"Part 1: خودت، بعد دوچرخه‌سواری"},"asks":{"en":"The examiner checks your name and asks about your work, studies or home, then four questions on one everyday topic. Here the topic is cycling.","tr":"Sınav görevlisi adını kontrol eder, işini, okulunu ya da evini sorar, sonra günlük bir konuda dört soru sorar. Burada konu bisiklet.","fa":"ممتحن اسمت را چک می‌کند، درباره‌ی کار، درس یا خانه‌ات می‌پرسد و بعد چهار سؤال درباره‌ی یک موضوع روزمره. این‌جا موضوع دوچرخه‌سواری است."},"fields":["Work or studies","Home","Riding a bike","Learning as a child","Cycling in your town","Bikes in the future"],"words":[{"a":"ride a bike","b":"cycle / go cycling","tr":"bisiklete binmek","fa":"دوچرخه‌سواری کردن"},{"a":"cycle lane","b":"a part of the road just for bikes","tr":"bisiklet yolu","fa":"مسیر دوچرخه"},{"a":"commute","b":"travel to work or school","tr":"işe ya da okula gidip gelmek","fa":"رفت‌وآمد به کار یا مدرسه"},{"a":"heavy traffic","b":"lots of cars / busy roads","tr":"yoğun trafik","fa":"ترافیک سنگین"},{"a":"hilly","b":"lots of steep streets","tr":"tepelik, yokuşlu","fa":"پرشیب، تپه‌ای"},{"a":"keep fit","b":"stay healthy / get exercise","tr":"formda kalmak","fa":"روی فرم ماندن"},{"a":"I learnt when I was","b":"my dad taught me at the age of","tr":"... yaşındayken öğrendim","fa":"وقتی ... ساله بودم یاد گرفتم"},{"a":"to be honest","b":"actually / if I’m honest","tr":"açıkçası","fa":"راستش"},{"a":"electric bike","b":"an e-bike / a bike with a small motor","tr":"elektrikli bisiklet","fa":"دوچرخه‌ی برقی"},{"a":"hire a bike","b":"rent one for an hour or a day","tr":"bisiklet kiralamak","fa":"دوچرخه کرایه کردن"}],"traps":[{"en":"One-word answers: \"Yes.\" or \"Sometimes.\" Give the answer and one reason or detail.","tr":"Tek kelimelik cevaplar: \"Yes.\" ya da \"Sometimes.\" Cevabı ve bir neden ya da ayrıntıyı ver.","fa":"جواب‌های یک‌کلمه‌ای: «Yes.» یا «Sometimes.». جواب و یک دلیل یا جزئیات بده."},{"en":"A memorised speech about the topic. Part 1 is a short, natural conversation: two or three sentences.","tr":"Konu hakkında ezberlenmiş bir konuşma. Part 1 kısa ve doğal bir sohbettir: iki üç cümle.","fa":"سخنرانیِ حفظ‌شده درباره‌ی موضوع. Part 1 یک گفتگوی کوتاه و طبیعی است: دو سه جمله."}],"example":{"text":"Q: \"Do you ride a bike these days?\"","item":"Which answer is the right length?","answer":"Not as much as I’d like. My town is very hilly, so I mostly walk or take the bus, but I hire a bike when I’m on holiday.","why":{"en":"An answer, a reason and a detail: about ten seconds.","tr":"Bir cevap, bir neden ve bir ayrıntı: yaklaşık on saniye.","fa":"یک جواب، یک دلیل و یک جزئیات: حدود ده ثانیه."}}},{"id":"x05-s2-ctx","exam":true,"patterns":["S2-object","PARA-discuss"],"often":{"pattern":"S2-object","n":10,"of":40,"label":{"en":"Comes up often in the real exam: 10 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 10’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۱۰ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 2: a show you would like to see again","tr":"Part 2: yeniden görmek istediğin bir gösteri","fa":"Part 2: اجرایی که دوست داری دوباره ببینی"},"asks":{"en":"The card asks you to describe a concert, play or show you have seen and would like to see again with friends. You have one minute to make notes, then talk for up to two minutes.","tr":"Kart, izlediğin ve arkadaşlarınla yeniden görmek istediğin bir konseri, oyunu ya da gösteriyi anlatmanı istiyor. Not almak için bir dakikan var, sonra iki dakikaya kadar konuşursun.","fa":"کارت از تو می‌خواهد کنسرت، نمایش یا اجرایی را توصیف کنی که دیده‌ای و دوست داری با دوستانت دوباره ببینی. یک دقیقه برای یادداشت داری و بعد تا دو دقیقه حرف می‌زنی."},"fields":["What the show was","When and where you saw it","What happened","Why you want to see it again with friends"],"words":[{"a":"performance","b":"show / concert / gig","tr":"gösteri, performans","fa":"اجرا"},{"a":"the audience","b":"the crowd / the people watching","tr":"seyirci","fa":"تماشاگرها"},{"a":"on stage","b":"in front of the audience","tr":"sahnede","fa":"روی صحنه"},{"a":"the atmosphere","b":"the feeling in the room","tr":"atmosfer, hava","fa":"حال‌وهوا"},{"a":"it blew me away","b":"I was amazed / I couldn’t believe it","tr":"beni büyüledi","fa":"محوش شدم"},{"a":"sold out","b":"no tickets left","tr":"biletler tükendi","fa":"بلیت‌ها تمام شد"},{"a":"live","b":"happening in front of you, not recorded","tr":"canlı","fa":"زنده"},{"a":"share the experience","b":"enjoy it together","tr":"deneyimi paylaşmak","fa":"تجربه را با هم شریک شدن"},{"a":"I’d love to","b":"I’d really like to / I’m dying to","tr":"çok isterim","fa":"خیلی دلم می‌خواهد"},{"a":"notice more","b":"see things I missed the first time","tr":"daha fazlasını fark etmek","fa":"چیزهای بیشتری دیدن"}],"traps":[{"en":"Talking only about the music or the actors and forgetting the last line: why you want to see it again, and why with friends.","tr":"Yalnızca müzikten ya da oyunculardan söz edip son satırı unutmak: neden yeniden görmek istediğin ve neden arkadaşlarla.","fa":"فقط از موسیقی یا بازیگرها حرف زدن و فراموش کردن خط آخر: چرا می‌خواهی دوباره ببینی و چرا با دوستانت."},{"en":"Stopping after one minute. The explain line is where you develop the talk to two minutes.","tr":"Bir dakika sonra durmak. Açıklama satırı, konuşmayı iki dakikaya taşıdığın yerdir.","fa":"بعد از یک دقیقه ساکت شدن. خط توضیح جایی است که صحبت را تا دو دقیقه گسترش می‌دهی."}],"example":{"text":"Notes (one minute): folk band · summer festival, 2 yrs ago · rain, everyone danced · go back with Leyla + Murat → they missed it, atmosphere","item":"How do you start?","answer":"I’d like to talk about a folk band I saw at a small summer festival two years ago, because it’s the one show I’d love to see again with my friends.","why":{"en":"The first sentence answers \"what\" and \"when\" and points to the explain line.","tr":"İlk cümle \"ne\" ve \"ne zaman\" sorularını cevaplıyor ve açıklama satırına işaret ediyor.","fa":"جمله‌ی اول به «چه» و «کی» جواب می‌دهد و به خط توضیح اشاره می‌کند."}}},{"id":"x05-s3-ctx","exam":true,"patterns":["S3-culture","PARA-discuss"],"often":{"pattern":"S3-culture","n":6,"of":40,"label":{"en":"Comes up often in the real exam: 6 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 6’sında","fa":"در آزمون واقعی زیاد می‌آید: در ۶ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 3: live performance and young people","tr":"Part 3: canlı performans ve gençler","fa":"Part 3: اجرای زنده و جوان‌ها"},"asks":{"en":"The examiner widens the Part 2 topic: why people go to live shows, ticket prices, young audiences and performing as a job. You give views about people in general, with reasons and examples.","tr":"Sınav görevlisi Part 2 konusunu genişletir: insanların neden canlı gösterilere gittiği, bilet fiyatları, genç izleyiciler ve sahne sanatlarının meslek olarak yapılması. Genel olarak insanlar hakkında nedenler ve örneklerle görüş bildirirsin.","fa":"ممتحن موضوع Part 2 را گسترده‌تر می‌کند: چرا مردم به اجرای زنده می‌روند، قیمت بلیت، تماشاگرهای جوان و اجرا به‌عنوان شغل. درباره‌ی آدم‌ها به‌طور کلی، با دلیل و مثال، نظر می‌دهی."},"fields":["Why people go to live shows","Live versus online","Ticket prices","Young audiences","Performing as a career","Support from the state"],"words":[{"a":"live entertainment","b":"concerts, theatre and comedy in front of an audience","tr":"canlı eğlence","fa":"سرگرمی زنده"},{"a":"streaming","b":"watching online / on a screen at home","tr":"çevrim içi izleme","fa":"تماشای آنلاین"},{"a":"ticket prices","b":"what it costs to get in","tr":"bilet fiyatları","fa":"قیمت بلیت"},{"a":"discount","b":"a cheaper price / reduced tickets","tr":"indirim","fa":"تخفیف"},{"a":"young audiences","b":"teenagers and young adults who come to watch","tr":"genç izleyiciler","fa":"تماشاگرهای جوان"},{"a":"subsidise","b":"pay part of the cost with public money","tr":"sübvanse etmek","fa":"یارانه دادن"},{"a":"an insecure career","b":"no regular income / hard to make a living","tr":"güvencesiz bir meslek","fa":"شغلی بی‌ثبات"},{"a":"talent","b":"natural ability","tr":"yetenek","fa":"استعداد"},{"a":"on the other hand","b":"that said / then again","tr":"öte yandan","fa":"از طرف دیگر"},{"a":"it depends on","b":"it varies with","tr":"... bağlı","fa":"بستگی دارد به"}],"traps":[{"en":"Talking only about yourself: Part 3 asks about people and society, not your own last concert.","tr":"Yalnızca kendinden söz etmek: Part 3 kendi son konserini değil, insanları ve toplumu sorar.","fa":"فقط از خودت حرف زدن: Part 3 درباره‌ی آدم‌ها و جامعه می‌پرسد، نه آخرین کنسرتی که خودت رفتی."},{"en":"A view with no support: \"Yes, I think so.\" Add a reason and an example, then the other side if it helps.","tr":"Desteksiz bir görüş: \"Yes, I think so.\" Bir neden ve örnek ekle, gerekirse karşı tarafı da söyle.","fa":"نظر بدون پشتوانه: «Yes, I think so.». یک دلیل و یک مثال اضافه کن و اگر کمک می‌کند طرف مقابل را هم بگو."}],"example":{"text":"Q: \"Why do some people prefer live music to recordings?\"","item":"Which answer has a view, a reason and an example?","answer":"Mainly for the shared experience, I think. At a concert you feel part of a crowd. When my brother saw his favourite band, he said the whole stadium sang together, and you can’t get that from headphones.","why":{"en":"View (shared experience), reason (feeling part of a crowd) and a real example (the brother’s concert).","tr":"Görüş (paylaşılan deneyim), neden (kalabalığın parçası olmak) ve gerçek bir örnek (ağabeyin konseri).","fa":"نظر (تجربه‌ی مشترک)، دلیل (حس بخشی از جمعیت بودن) و یک مثال واقعی (کنسرت برادر)."}}},{"id":"S2-media","ctx":["S2-object","S2-media"],"title":{"en":"A film, a book or a programme","tr":"Bir film, bir kitap ya da bir program","fa":"یک فیلم، یک کتاب یا یک برنامه"},"asks":{"en":"A card about something you watched or read: a film or play to see again, a review, a book that made you think, a useful website. 2026 reports add a TV programme you enjoy and a recent film.","tr":"İzlediğin ya da okuduğun bir şey hakkında kart: yeniden görmek istediğin bir film ya da oyun, bir eleştiri yazısı, seni düşündüren bir kitap, işe yarar bir internet sitesi. 2026 raporları sevdiğin bir TV programını ve yakın zamanda izlediğin bir filmi ekliyor.","fa":"کارتی درباره‌ی چیزی که دیده یا خوانده‌ای: فیلم یا نمایشی که دوست داری دوباره ببینی، یک نقد، کتابی که به فکرت انداخت، یک وب‌سایت مفید. گزارش‌های ۲۰۲۶ یک برنامه‌ی تلویزیونی محبوب و یک فیلم تازه را هم اضافه می‌کنند."},"fields":["Describe a film you would like to watch again.","Describe a book that made you think.","Describe a TV programme you enjoy.","Describe a website you use often.","Describe a review you read."],"words":[{"a":"film","b":"a drama / a documentary","tr":"dram, belgesel","fa":"درام، مستند"},{"a":"story","b":"the plot / it's about","tr":"konusu","fa":"داستانش"},{"a":"main person","b":"the main character / the lead actor","tr":"baş karakter","fa":"شخصیت اصلی"},{"a":"it was good","b":"gripping / moving / thought-provoking","tr":"sürükleyici, dokunaklı","fa":"گیرا، تأثیرگذار"},{"a":"it was bad","b":"slow / disappointing","tr":"ağır, hayal kırıklığı","fa":"کند، ناامیدکننده"},{"a":"the end","b":"the ending / the twist at the end","tr":"son, sürpriz son","fa":"پایان، غافلگیری آخر"},{"a":"I found it","b":"I came across it on a streaming site","tr":"bir yayın sitesinde rastladım","fa":"در یک سایت تماشای آنلاین پیدایش کردم"},{"a":"I read about it","b":"I read a review of it","tr":"eleştirisini okudum","fa":"نقدش را خواندم"},{"a":"it made me think","b":"it changed the way I see","tr":"bakış açımı değiştirdi","fa":"نگاهم را عوض کرد"},{"a":"the music","b":"the soundtrack","tr":"film müziği","fa":"موسیقی متن"},{"a":"happens in","b":"it's set in","tr":"... -de geçiyor","fa":"در ... می‌گذرد"},{"a":"you should watch it","b":"I'd recommend it to anyone who","tr":"... herkese öneririm","fa":"به هر کسی که ... پیشنهادش می‌کنم"}],"traps":[{"en":"Retelling the whole plot uses all your time. Give the story in two sentences and spend the rest on your reaction.","tr":"Bütün konuyu anlatmak tüm süreni yer. Konuyu iki cümlede ver, kalanını kendi tepkine ayır.","fa":"تعریف کل داستان همه‌ی وقتت را می‌گیرد. داستان را در دو جمله بگو و بقیه را به واکنش خودت بده."},{"en":"Present simple for the story (\"she travels...\"), past simple for your experience (\"I watched it...\").","tr":"Konu için geniş zaman (\"she travels...\"), kendi deneyimin için geçmiş zaman (\"I watched it...\").","fa":"حال ساده برای داستان («she travels...»)، گذشته‌ی ساده برای تجربه‌ی خودت («I watched it...»)."}],"example":{"lines":[["Candidate","The film is about a woman who walks across a desert with four camels."],["Candidate","I watched it on a long flight, and I couldn’t stop thinking about it afterwards."],["Candidate","What I remember most is how quiet it is: there’s hardly any music."]],"item":"Which tenses does the speaker use, and why?","answer":"Present simple for the story, past simple for when she watched it, present for what she remembers now.","why":{"en":"Each tense has a job, so the listener always knows which time you mean.","tr":"Her zamanın bir görevi var; dinleyen hangi zamanı kastettiğini hep bilir.","fa":"هر زمان کاری دارد، پس شنونده همیشه می‌فهمد منظورت کدام زمان است."}},"ideas":["when and where you watched or read it","the story in two sentences, not the whole plot","a scene you remember","who you would recommend it to","why it matters (explain)"],"general":true,"patterns":["S2-object"],"often":{"pattern":"S2-object","n":10,"of":40,"label":{"en":"Comes up often in the real exam: 10 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 10’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۱۰ آزمون از ۴۰ آزمونِ اخیر"}}},{"id":"S3-culture","ctx":["S3-culture"],"title":{"en":"Culture and the built environment","tr":"Kültür ve yapılı çevre","fa":"فرهنگ و محیط ساخته‌شده"},"asks":{"en":"General questions linked to the Part 2 card, about theatre and cinema, statues and old buildings, science and research, and homes of the future. The examiner wants an opinion, a reason, an example and, when it helps, the other side.","tr":"Part 2 kartına bağlı, tiyatro ve sinema, heykeller ve eski binalar, bilim ve araştırma, geleceğin evleri hakkında genel sorular. Sınav görevlisi bir görüş, bir neden, bir örnek ve gerektiğinde karşı tarafı ister.","fa":"سؤال‌های کلی مرتبط با کارت Part 2، درباره‌ی تئاتر و سینما، مجسمه‌ها و ساختمان‌های قدیمی، علم و پژوهش، و خانه‌های آینده. ممتحن یک نظر، یک دلیل، یک مثال و هرجا لازم بود طرف مقابل را می‌خواهد."},"fields":["Why is it important to protect old buildings?","Is the cinema still popular?","Should cities have more statues and public art?","How will homes change in the future?","Should governments pay for scientific research?"],"words":[{"a":"old buildings","b":"historic buildings / heritage sites","tr":"tarihî binalar","fa":"بناهای تاریخی"},{"a":"keep","b":"preserve / restore","tr":"korumak, restore etmek","fa":"حفظ کردن، مرمت کردن"},{"a":"modern","b":"contemporary","tr":"çağdaş","fa":"معاصر"},{"a":"ugly","b":"an eyesore","tr":"göz zevkini bozan","fa":"زشت و ناخوشایند"},{"a":"city look","b":"the skyline / architecture","tr":"şehrin silueti, mimari","fa":"منظره‌ی شهر، معماری"},{"a":"public art","b":"statues and murals","tr":"kamusal sanat","fa":"هنر عمومی"},{"a":"identity","b":"a sense of history","tr":"kimlik, tarih bilinci","fa":"هویت، حس تاریخ"},{"a":"plays","b":"live theatre / performances","tr":"tiyatro oyunları","fa":"اجرای زنده"},{"a":"watch at home","b":"stream films","tr":"evde izlemek","fa":"آنلاین تماشا کردن"},{"a":"research","b":"scientific studies","tr":"bilimsel çalışmalar","fa":"پژوهش علمی"},{"a":"paid by the state","b":"publicly funded","tr":"kamu tarafından finanse edilen","fa":"با بودجه‌ی دولتی"},{"a":"in future","b":"in the coming decades","tr":"önümüzdeki on yıllarda","fa":"در دهه‌های آینده"}],"traps":[{"en":"Abstract questions need a concrete example: name a building, a film or a discovery.","tr":"Soyut sorular somut bir örnek ister: bir bina, bir film ya da bir buluşun adını ver.","fa":"سؤال‌های انتزاعی مثال مشخص می‌خواهند: اسم یک ساختمان، فیلم یا کشف را بیاور."},{"en":"If you do not know much about the topic, say what you think and why. There is no wrong opinion.","tr":"Konuyu çok bilmiyorsan ne düşündüğünü ve nedenini söyle. Yanlış görüş diye bir şey yok.","fa":"اگر درباره‌ی موضوع زیاد نمی‌دانی، بگو چه فکر می‌کنی و چرا. نظر غلط وجود ندارد."}],"example":{"lines":[["Examiner","Why is it important to protect old buildings?"],["Candidate","Mainly because they show where a city has come from."],["Candidate","In my hometown, the old market hall reminds everyone of the time when the town was a trading centre."],["Candidate","Having said that, I don’t think every old building should be kept, if it is unsafe or empty."]],"item":"Which moves does the answer make?","answer":"Opinion with a reason, a named example, then a limit (\"Having said that...\").","why":{"en":"A named example turns an abstract idea into something the examiner can picture.","tr":"Adı verilen bir örnek soyut bir fikri sınav görevlisinin gözünde canlandırabileceği bir şeye çevirir.","fa":"مثال نام‌دار یک ایده‌ی انتزاعی را به چیزی تبدیل می‌کند که ممتحن بتواند تصورش کند."}},"ideas":["old buildings give a city its identity","restoration is expensive; new buildings are efficient","live theatre offers something screens cannot","public money for research benefits everyone"],"general":true,"patterns":["S3-culture"],"often":{"pattern":"S3-culture","n":6,"of":40,"label":{"en":"Comes up often in the real exam: 6 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 6’sında","fa":"در آزمون واقعی زیاد می‌آید: در ۶ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Three parts, one examiner","tr":"Üç kısım, bir sınav görevlisi","fa":"سه بخش، یک ممتحن"},"body":{"en":"Part 1 (4-5 minutes): questions about you and one everyday topic. Part 2 (3-4 minutes): one minute to prepare, then up to two minutes alone, then one short question. Part 3 (4-5 minutes): a discussion of general questions. The test is recorded.","tr":"Part 1 (4-5 dakika): seninle ve günlük bir konuyla ilgili sorular. Part 2 (3-4 dakika): bir dakika hazırlık, sonra iki dakikaya kadar tek başına konuşma, sonra kısa bir soru. Part 3 (4-5 dakika): genel soruların tartışması. Sınav kaydedilir.","fa":"Part 1 (۴ تا ۵ دقیقه): سؤال‌هایی درباره‌ی خودت و یک موضوع روزمره. Part 2 (۳ تا ۴ دقیقه): یک دقیقه آماده شدن، بعد تا دو دقیقه حرف زدن به‌تنهایی و بعد یک سؤال کوتاه. Part 3 (۴ تا ۵ دقیقه): بحث درباره‌ی سؤال‌های کلی. آزمون ضبط می‌شود."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"One move for each part","tr":"Her kısım için bir hamle","fa":"برای هر بخش یک حرکت"},"steps":[{"en":"Part 1: answer, then add a reason or a detail. Two or three sentences.","tr":"Part 1: cevapla, sonra bir neden ya da ayrıntı ekle. İki üç cümle.","fa":"Part 1: جواب بده، بعد یک دلیل یا جزئیات اضافه کن. دو سه جمله."},{"en":"Part 2: in the minute, write one key word for each line of the card, and two for the last line.","tr":"Part 2: o bir dakikada kartın her satırı için bir, son satır için iki anahtar kelime yaz.","fa":"Part 2: در آن یک دقیقه برای هر خط کارت یک کلیدواژه و برای خط آخر دو کلیدواژه بنویس."},{"en":"Part 2: describe the show, then spend the most time on why you want to see it again.","tr":"Part 2: gösteriyi anlat, sonra en çok zamanı neden yeniden görmek istediğine ayır.","fa":"Part 2: اجرا را توصیف کن و بیشترین وقت را روی اینکه چرا می‌خواهی دوباره ببینی‌اش بگذار."},{"en":"Part 3: give a view, a reason, an example, and the other side when it helps.","tr":"Part 3: bir görüş, bir neden, bir örnek ve gerektiğinde karşı tarafı ver.","fa":"Part 3: یک نظر، یک دلیل، یک مثال و هرجا کمک کرد طرف مقابل را بگو."}]},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Describing a show and wanting more","tr":"Bir gösteriyi anlatmak ve tekrarını istemek","fa":"توصیف یک اجرا و خواستنِ دوباره‌اش"},"table":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["the scene (past continuous)","We were standing near the front when..."],["what happened (past simple)","The singer stopped and asked everyone to sing."],["a wish (would like to)","I’d love to see it again because..."],["why with friends","It would be even better with..., because..."],["a view in Part 3","I’d say that... / On the other hand,..."]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"A Part 3 answer, step by step","tr":"Bir Part 3 cevabı, adım adım","fa":"یک جواب Part 3، قدم به قدم"},"instruction":"Examiner: \"Should museums be free for young people?\"","item":"Answer with four moves.","answer":"Yes, I think they should. Young people often have very little money, and a free visit can start a lifelong interest. In my city, for instance, the art gallery is free for under-25s and it’s always full of students. That said, someone has to pay, so the government may need to help.","walk":[{"en":"View: \"Yes, I think they should.\"","tr":"Görüş: \"Yes, I think they should.\"","fa":"نظر: «Yes, I think they should.»"},{"en":"Reason and example: little money; the free gallery full of students.","tr":"Neden ve örnek: az para; öğrencilerle dolu ücretsiz galeri.","fa":"دلیل و مثال: پول کم؛ گالری رایگانی که پر از دانشجوست."},{"en":"The other side: \"That said, someone has to pay...\"","tr":"Karşı taraf: \"That said, someone has to pay...\"","fa":"طرف مقابل: «That said, someone has to pay...»"}]},"quick":{"prompt":"Part 1. Examiner: \"Is your town good for cycling?\" Which answer is best?","options":["No.","Cycling was invented in the nineteenth century and today there are many kinds of bike...","Not really. The roads are narrow and busy, so most people only cycle in the park."],"correct":2,"why":{"en":"An answer plus a reason and a detail. \"No.\" is too short; the history of the bicycle is a speech, not a conversation.","tr":"Bir cevap, bir neden ve bir ayrıntı. \"No.\" çok kısa; bisikletin tarihi sohbet değil, nutuk.","fa":"یک جواب با یک دلیل و یک جزئیات. «No.» خیلی کوتاه است؛ تاریخچه‌ی دوچرخه سخنرانی است، نه گفتگو."}},"remember":{"en":"Part 1 short and natural, Part 2 a clear picture plus a real reason, Part 3 view, reason, example.","tr":"Part 1 kısa ve doğal, Part 2 net bir tablo ve gerçek bir neden, Part 3 görüş, neden, örnek.","fa":"Part 1 کوتاه و طبیعی، Part 2 تصویری روشن و یک دلیل واقعی، Part 3 نظر، دلیل، مثال."},"type":"explain","id":"c-x05-s-e","course":"ielts-exams","exam":"exam-05","unit":"x05-s"},"sets":{"title":{"en":"The Speaking test","tr":"Speaking sınavı","fa":"آزمون Speaking"},"note":{"en":"Do the three parts in order, without a break, as in the real test. Record yourself if you can, then use the self-check under each part.","tr":"Gerçek sınavdaki gibi üç kısmı sırayla ve ara vermeden yap. Yapabilirsen kendini kaydet, sonra her kısmın altındaki öz değerlendirmeyi kullan.","fa":"سه بخش را به ترتیب و بدون مکث انجام بده، مثل آزمون واقعی. اگر می‌توانی صدایت را ضبط کن و بعد از خودارزیابیِ زیر هر بخش استفاده کن."},"sequential":true,"examinerVoice":{"accent":"British (standard Southern)","gender":"F","tts":{"engine":"kokoro","voice":"bf_emma"},"role":"Examiner"},"sets":[{"part":"Part 1","ctx":["S1-frame","S1-places"],"minutes":[4,5],"title":{"en":"Part 1: about you, then cycling","tr":"Part 1: senin hakkında, sonra bisiklet","fa":"Part 1: درباره‌ی خودت، بعد دوچرخه‌سواری"},"examinerIntro":["Good afternoon. My name is Clare Hadley. Can you tell me your full name, please?","Thank you. And can I see your identification, please?","Thank you. Now, in this first part, I’d like to ask you some questions about yourself."],"frame":["Let’s talk about what you do. Do you work or are you a student?","Why did you choose that job or that subject?","Let’s talk about your home. What do you like most about the area where you live?"],"topicIntro":"Now let’s talk about cycling.","questions":["How often do you ride a bike?","When did you learn to ride a bike? [Who taught you?]","Is your town a good place for cycling? [Why/Why not?]","Do you think more people will cycle in the future?"],"model":"Q: How often do you ride a bike?\nA: Only at weekends, really. During the week I take the bus to work, but on Saturdays I often cycle along the river with a friend.\n\nQ: When did you learn to ride a bike?\nA: When I was about six. My grandfather taught me in a car park on Sunday mornings, and I fell off more times than I can remember.\n\nQ: Is your town a good place for cycling?\nA: Not especially. The centre is quite hilly and the roads are narrow, so a lot of people find it a bit dangerous. There are a few new cycle lanes, though.\n\nQ: Do you think more people will cycle in the future?\nA: Probably, yes. Electric bikes make hills much easier, and as fuel gets more expensive, I think more people will try them for short journeys.","moves":[{"label":{"en":"Answer first","tr":"Önce cevap","fa":"اول جواب"},"example":"Only at weekends, really."},{"label":{"en":"Add a reason or a detail","tr":"Bir neden ya da ayrıntı ekle","fa":"یک دلیل یا جزئیات اضافه کن"},"example":"The centre is quite hilly and the roads are narrow, so a lot of people find it a bit dangerous."},{"label":{"en":"A small contrast or a then/now","tr":"Küçük bir karşıtlık ya da o zaman/şimdi","fa":"یک تضاد کوچک یا «آن موقع/حالا»"},"example":"There are a few new cycle lanes, though."}],"selfCheck":[{"en":"I answered every question with two or three sentences, not one word.","tr":"Her soruyu tek kelimeyle değil, iki üç cümleyle cevapladım.","fa":"به هر سؤال با دو سه جمله جواب دادم، نه یک کلمه."},{"en":"I added a reason or a detail after each answer.","tr":"Her cevaptan sonra bir neden ya da ayrıntı ekledim.","fa":"بعد از هر جواب یک دلیل یا جزئیات اضافه کردم."},{"en":"I used the right tense: present for habits, past for childhood, will for the future.","tr":"Doğru zamanı kullandım: alışkanlıklar için geniş zaman, çocukluk için geçmiş, gelecek için will.","fa":"زمان درست را به کار بردم: حال برای عادت‌ها، گذشته برای بچگی، will برای آینده."}]},{"part":"Part 2","ctx":["S2-object"],"minutes":[3,4],"title":{"en":"Part 2: a show you would like to see again","tr":"Part 2: yeniden görmek istediğin bir gösteri","fa":"Part 2: اجرایی که دوست داری دوباره ببینی"},"examinerIntro":["Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. Before you talk, you’ll have one minute to think about what you’re going to say. You can make some notes if you wish. Do you understand?","Here’s some paper and a pencil for making notes, and here’s your topic. I’d like you to describe a concert or a show you have seen that you would like to see again with your friends.","All right? Remember you have one to two minutes for this. Don’t worry if I stop you. I’ll tell you when the time is up. Can you start speaking now, please?"],"card":{"task":"Describe a concert or a show you have seen that you would like to see again with your friends.","bullets":["what the show was","when and where you saw it","what happened during the show","and explain why you would like to see it again with your friends"]},"prep":60,"talk":120,"roundingOff":["Do you usually go to shows alone or with other people?"],"model":"I’d like to talk about a folk band I saw at a small summer festival two years ago, because it’s the one show I’d really love to see again with my friends.\n\nThe festival was in a field outside a village, and there were only about two thousand people there, which made it feel very relaxed. I went with my cousin, almost by accident, because someone had given her two spare tickets.\n\nThe band came on just as it started to rain. Everyone expected people to run for the tents, but the singer told us to take our shoes off and dance, and within a minute the whole field was dancing in the mud. They played for nearly two hours, and at the end they came down from the stage and sang the last song in the middle of the crowd, without microphones.\n\nSo why would I like to go again with my friends? Mainly because I’ve tried to describe that evening to them so many times, and they just look at me politely. I want them to feel the atmosphere for themselves. Also, the first time I was so surprised that I hardly noticed the music itself, and I think I’d enjoy the songs more the second time. And honestly, dancing in the rain is much more fun with people you know well.","moves":[{"label":{"en":"Start with what and when","tr":"Ne ve ne zamanla başla","fa":"با «چه» و «کی» شروع کن"},"example":"I’d like to talk about a folk band I saw at a small summer festival two years ago..."},{"label":{"en":"Describe the moment that made it special","tr":"Onu özel yapan anı anlat","fa":"لحظه‌ای را که آن را خاص کرد توصیف کن"},"example":"The band came on just as it started to rain... the whole field was dancing in the mud."},{"label":{"en":"Spend time on the explain line, with two or three reasons","tr":"Açıklama satırına zaman ayır, iki üç nedenle","fa":"روی خط توضیح وقت بگذار، با دو سه دلیل"},"example":"Mainly because... Also,... And honestly, dancing in the rain is much more fun with people you know well."}],"selfCheck":[{"en":"I covered all four lines of the card and spoke for close to two minutes.","tr":"Kartın dört satırının hepsini ele aldım ve iki dakikaya yakın konuştum.","fa":"هر چهار خط کارت را گفتم و نزدیک دو دقیقه حرف زدم."},{"en":"I described one special moment in detail, not the whole programme.","tr":"Programın tamamını değil, özel bir anı ayrıntılı anlattım.","fa":"یک لحظه‌ی خاص را با جزئیات توصیف کردم، نه کل برنامه را."},{"en":"I gave more than one reason for wanting to see it again with friends.","tr":"Arkadaşlarla yeniden görmek istemem için birden fazla neden verdim.","fa":"برای اینکه چرا می‌خواهم با دوستانم دوباره ببینمش بیش از یک دلیل آوردم."}]},{"part":"Part 3","ctx":["S3-culture"],"minutes":[4,5],"title":{"en":"Part 3: live performance and young audiences","tr":"Part 3: canlı performans ve genç izleyiciler","fa":"Part 3: اجرای زنده و تماشاگرهای جوان"},"examinerIntro":["We’ve been talking about a show you would like to see again, and I’d like to discuss with you one or two more general questions related to this."],"subtopics":[{"title":"Live performance","questions":["Why do people still go to live concerts and plays when they can watch so much online?","Are tickets for live shows too expensive in your country?","How could theatres and concert halls attract more young people?"]},{"title":"Performing as a career","questions":["Why do so many young people dream of becoming actors or musicians?","What are the difficulties of earning a living as a performer?","Should governments give money to support the arts?"]}],"model":"Q: How could theatres and concert halls attract more young people?\nA: I think price is the main thing. Many young people would love to go, but a theatre ticket can cost as much as a week’s food. Some theatres in my country now sell the last fifty seats for very little to anyone under twenty-five, and those shows are often full of students. Programmes matter too: if young people never see their own lives on stage, they won’t feel it’s for them.\n\nQ: Should governments give money to support the arts?\nA: Yes, to some extent. Without public money, many small theatres and orchestras would simply close, because ticket sales rarely cover their costs. On the other hand, the money has to be spent fairly, so that it doesn’t only go to big institutions in the capital. Supporting music lessons in schools, for example, probably does more good than funding one more opera house.","moves":[{"label":{"en":"Give a clear view","tr":"Net bir görüş ver","fa":"نظرت را روشن بگو"},"example":"I think price is the main thing."},{"label":{"en":"Support it: reason + example","tr":"Destekle: neden + örnek","fa":"پشتیبانی کن: دلیل + مثال"},"example":"Some theatres in my country now sell the last fifty seats for very little to anyone under twenty-five..."},{"label":{"en":"Show the other side or a limit","tr":"Karşı tarafı ya da bir sınırı göster","fa":"طرف مقابل یا یک محدودیت را نشان بده"},"example":"On the other hand, the money has to be spent fairly..."}],"selfCheck":[{"en":"I gave a clear view in my first sentence.","tr":"İlk cümlemde net bir görüş verdim.","fa":"در جمله‌ی اولم نظر روشنی دادم."},{"en":"I supported it with a reason and a real example.","tr":"Onu bir neden ve gerçek bir örnekle destekledim.","fa":"آن را با یک دلیل و یک مثال واقعی پشتیبانی کردم."},{"en":"I talked about people in general, not only about myself.","tr":"Yalnızca kendimden değil, genel olarak insanlardan söz ettim.","fa":"درباره‌ی آدم‌ها به‌طور کلی حرف زدم، نه فقط خودم."}]}],"type":"sets","id":"c-x05-s-p","course":"ielts-exams","exam":"exam-05","unit":"x05-s"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"Most people commute by bus.\" To commute is to...","options":["go on holiday","travel regularly to work or school","visit friends"],"correct":1,"why":{"en":"Commute = make the same journey to work or school every day.","tr":"Commute = her gün işe ya da okula aynı yolculuğu yapmak.","fa":"commute یعنی هر روز همان مسیر را تا کار یا مدرسه رفتن."}},{"tests":"paraphrase","point":3,"prompt":"Which phrase means \"the government pays part of the cost\"?","options":["the arts are subsidised","the arts are sold out","the arts are streamed"],"correct":0,"why":{"en":"To subsidise = to pay part of the cost with public money.","tr":"Subsidise = maliyetin bir kısmını kamu parasıyla ödemek.","fa":"subsidise یعنی بخشی از هزینه را با پول عمومی دادن."}},{"tests":"method","point":2,"prompt":"Your card ends \"and explain why you would like to see it again with your friends\". How should you plan your minute?","options":["Write the first sentence in full","Only note the name of the show","Note two or three reasons for the last line"],"correct":2,"why":{"en":"The last line is where you reach two minutes, so plan more than one reason for it.","tr":"Son satır iki dakikaya ulaştığın yerdir; onun için birden fazla neden planla.","fa":"خط آخر جایی است که به دو دقیقه می‌رسی، پس برایش بیش از یک دلیل برنامه‌ریزی کن."}},{"tests":"trap","point":2,"prompt":"After describing the show for a minute, you have said nothing about your friends. What do you do?","options":["Stop: you have described the show","Move to the explain line: why again, and why with friends","Describe the show again in more detail"],"correct":1,"why":{"en":"The card asks why you would see it again with friends; leaving it out leaves the talk incomplete.","tr":"Kart, neden arkadaşlarla yeniden göreceğini soruyor; bunu atlamak konuşmayı eksik bırakır.","fa":"کارت می‌پرسد چرا می‌خواهی با دوستانت دوباره ببینی؛ نگفتنش صحبت را ناقص می‌کند."}},{"tests":"method","point":2,"prompt":"Part 3: \"Are concert tickets too expensive?\" Which answer has the most complete structure?","options":["Often, yes. Big concerts can cost a week’s wages, so many students never go. Smaller venues are still affordable, though.","Yes.","I paid a lot for my last ticket."],"correct":0,"why":{"en":"The first answer has a view, a reason, an example and a limit; the last one talks only about the speaker.","tr":"İlk cevapta görüş, neden, örnek ve bir sınır var; sonuncusu yalnızca konuşanın kendisinden söz ediyor.","fa":"جواب اول نظر، دلیل، مثال و یک محدودیت دارد؛ جواب آخر فقط از خود گوینده حرف می‌زند."}}],"id":"c-x05-s-x","course":"ielts-exams","exam":"exam-05","unit":"x05-s"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
